    vocabulary: ['area', 'base', 'height', 'parallelogram', 'polygon', 'polyhedron', 'net', 'surface area', 'squared', 'cubed'],
    parentTips: ['Keep tracing paper, graph paper and scissors handy; cutting and rearranging shapes is the point.', 'Ask "Which side is the base, and where is its height?" before using any formula.', 'Have the student find the surface area of a cereal box using its net.'],
